# Entirely project-generated software fixture. No patient records or package data.
args <- commandArgs(trailingOnly = TRUE); out <- args[1]; dir.create(out, recursive = TRUE, showWarnings = FALSE)
set.seed(9182); n <- 160L; ids <- sprintf("synthetic_%03d", seq_len(n))
signal <- rnorm(n); covar1 <- rnorm(n); covar2 <- rbinom(n, 1, .45)
latent_event <- rexp(n, rate = exp(.45 * signal + .3 * covar1 - .25 * covar2) / 200)
censor <- rexp(n, rate = 1/350)
followup <- pmax(.1, round(pmin(latent_event, censor), 1)); event <- as.integer(latent_event <= censor)
E <- matrix(rnorm(160 * n, mean = 8, sd = 1), nrow = 160, dimnames = list(paste0("SIM", seq_len(160)), ids))
E[1, ] <- signal; rownames(E)[1] <- "SIM_SIGNAL"
write.csv(data.frame(feature_id = rownames(E), E, check.names = FALSE), file.path(out, "expression.csv"), row.names = FALSE)
write.csv(data.frame(sample = ids, condition = rep(c("A", "B"), length.out = n)), file.path(out, "samples.csv"), row.names = FALSE)
clinical <- data.frame(unit = ids, time = followup, event = event, covar1 = covar1, covar2 = covar2)
write.csv(clinical, file.path(out, "clinical.csv"), row.names = FALSE)
write.csv(data.frame(original_row = integer(), reason = character()), file.path(out, "fixture_exclusions.csv"), row.names = FALSE)
jsonlite::write_json(list(schema = "omicstat.synthetic-fixture.v1", source = "Project-generated independent random variables and exponential event/censoring times", seed = 9182L, n_units = n, measured_people = FALSE, uses_package_datasets = FALSE, time_units = "arbitrary simulation units", excluded_rows = 0L), file.path(out, "SYNTHETIC_INPUT_PROVENANCE.json"), auto_unbox = TRUE, pretty = TRUE)
z <- clinical; z$event[1] <- 2; write.csv(z, file.path(out, "bad-event.csv"), row.names = FALSE)
z <- clinical; z$time[1] <- 0; write.csv(z, file.path(out, "zero-time.csv"), row.names = FALSE)
z <- clinical; z$covar1[1] <- NA; write.csv(z, file.path(out, "missing-covariate.csv"), row.names = FALSE)
write.csv(rbind(clinical, clinical[1, ]), file.path(out, "duplicate.csv"), row.names = FALSE)
write.csv(clinical[-1, ], file.path(out, "missing-subject.csv"), row.names = FALSE)
